WITH filtered AS (SELECT *, COALESCE(browser, 'N/A') browser_filled FROM sessions WHERE started_at >= TO_DATE('2023-07-23') AND customer_id IS NOT NULL) SELECT device, COUNT(DISTINCT country) AS distinct_countries, COUNT(DISTINCT country) AS distinct_countries_2, MAX(started_at) AS ended_at, COUNT(*) FILTER (WHERE device = 'mobile') AS mobile_rows, COUNT(*) AS row_count, COUNT(*) AS cnt FROM filtered GROUP BY ROLLUP (device) HAVING COUNT(*) < 1000
